<template><section class="extension-page"><header><h2>数据源运维</h2><div class="actions"><el-button :loading="busy" @click="refresh">刷新表目录</el-button><el-button type="primary" :loading="busy" @click="backup">下载备份</el-button></div></header>
<el-tabs v-model="tab"><el-tab-pane label="表目录与备份" name="tables"><el-card><p>勾选要备份的表；未勾选时备份当前数据库全部表。备份文件包含数据，请妥善保存。</p><el-table :data="tables.map(name=>({name}))" @selection-change="selected=$event.map((x:any)=>x.name)"><el-table-column type="selection" width="48"/><el-table-column prop="name" label="表名"/></el-table></el-card></el-tab-pane>
<el-tab-pane label="SQL 工作台" name="sql"><el-card><p>仅操作本插件 plugin_ds_ 前缀表，SQL 使用宿主已有白名单约束。</p><el-input v-model="sql" type="textarea" :rows="8" placeholder="SELECT * FROM plugin_ds_migration"/><div class="actions" style="margin-top:16px"><el-button type="primary" :loading="busy" @click="execute('query')">查询</el-button><el-button type="warning" :loading="busy" @click="execute('ddl')">执行 DDL</el-button><el-button type="danger" :loading="busy" @click="execute('update')">执行数据变更</el-button></div><pre v-if="result">{{JSON.stringify(result,null,2)}}</pre></el-card></el-tab-pane>
<el-tab-pane label="恢复备份" name="restore"><el-card><p>恢复可能覆盖数据库数据。请先备份，并仅选择可信的 SQL / SQL.GZ 文件。</p><input type="file" accept=".sql,.gz" @change="choose"/><el-button type="danger" :loading="busy" :disabled="!file" @click="restore">恢复选定备份</el-button></el-card></el-tab-pane></el-tabs></section></template>
<script setup lang="ts">
import {ref,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {call,http} from './api';import './style.css';
const tab=ref('tables'),busy=ref(false),tables=ref<string[]>([]),selected=ref<string[]>([]),sql=ref('SELECT * FROM plugin_ds_migration'),result=ref<any>(),file=ref<File>();
async function run(fn:()=>Promise<void>){busy.value=true;try{await fn()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message)}finally{busy.value=false}}
function refresh(){return run(async()=>{tables.value=await call('/ds/backup/catalog-tables')})}
function execute(kind:string){return run(async()=>{if(!sql.value.trim())throw new Error('请输入 SQL');if(kind!=='query')await ElMessageBox.confirm('该操作会修改数据库，请确认 SQL 并确保已有备份。','执行确认',{type:'warning'});result.value=await call(kind==='ddl'?'/ds/schema/ddl':'/ds/data/'+kind,{sql:sql.value,args:[]})})}
function backup(){return run(async()=>{const r=await http.post('/ds/backup/export',{tables:selected.value,gzip:true},{responseType:'blob'});if(r.data.type.includes('json'))throw new Error('备份失败，请检查权限与服务状态');const url=URL.createObjectURL(r.data);const a=document.createElement('a');a.href=url;a.download='mms-backup-'+new Date().toISOString().slice(0,10)+'.sql.gz';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
function choose(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]}
function restore(){return run(async()=>{const f=file.value!;if(f.size>20*1024*1024)throw new Error('恢复文件不能超过 20MB');await ElMessageBox.prompt('输入 RESTORE 确认执行数据库恢复。','恢复确认',{inputPattern:/^RESTORE$/,inputErrorMessage:'请输入 RESTORE'});const buffer=new Uint8Array(await f.arrayBuffer());let binary='';for(let i=0;i<buffer.length;i+=8192)binary+=String.fromCharCode(...buffer.subarray(i,i+8192));await call('/ds/backup/import-b64',{data:btoa(binary),gzip:f.name.endsWith('.gz')});ElMessage.success('恢复完成');await refresh()})}
onMounted(refresh);
</script>
